package com.sahyog.datacollection.service.impl;
import com.sahyog.datacollection.dto.disability.*;
import com.sahyog.datacollection.service.DisabilityService;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import java.sql.*;
import java.time.*;
import java.time.format.DateTimeParseException;
import java.util.*;
import java.util.regex.Pattern;
@Service
public class DisabilityServiceImpl implements DisabilityService {
 private static final String SUMMARY="DC013",DETAILS="DC014";private static final Pattern NUMBER=Pattern.compile("[AD]\\d{7}");private final JdbcTemplate jdbc;
 public DisabilityServiceImpl(JdbcTemplate jdbc){this.jdbc=jdbc;}
 @Override @Transactional(readOnly=true) public DisabilitySummaryInitializeResponse initializeSummary(DisabilitySummaryInitializeRequest r){String c=resolve(r==null?null:r.appOrCaseNum());ensureApplication(c);List<DisabilitySummaryItem> rows=jdbc.query("SELECT d.DISABILITY_ID,d.PERSON_ID,p.FIRST_NAME,p.MIDDLE_NAME,p.LAST_NAME,p.AGE,d.DISABILITY_TYPES,d.OTHER_DISABILITY_DETAILS FROM DC_DISABILITY d JOIN DC_PERSON p ON p.PERSON_ID=d.PERSON_ID AND p.APPLICATION_NO=d.APPLICATION_NO WHERE d.APPLICATION_NO=? ORDER BY d.DISABILITY_ID",(s,n)->new DisabilitySummaryItem(s.getLong("DISABILITY_ID"),s.getLong("PERSON_ID"),name(s),s.getInt("AGE"),types(s.getString("DISABILITY_TYPES")),s.getString("OTHER_DISABILITY_DETAILS")),c);return new DisabilitySummaryInitializeResponse(c,SUMMARY,rows,!rows.isEmpty());}
 @Override public DisabilitySummaryNavigationResponse summaryNext(DisabilitySummaryNavigationRequest r){return summaryNav(validateNav(r),"DC015",null,null);}
 @Override public DisabilitySummaryNavigationResponse summaryPrevious(DisabilitySummaryNavigationRequest r){return summaryNav(validateNav(r),"DC012",null,null);}
 @Override public DisabilitySummaryNavigationResponse addNew(DisabilitySummaryNavigationRequest r){return summaryNav(validateNav(r),DETAILS,"ADD",null);}
 @Override @Transactional(readOnly=true) public DisabilitySummaryNavigationResponse edit(DisabilityRowRequest r){validateRow(r);String c=resolve(r.appOrCaseNum());ensureDisability(c,r.disabilityId());return summaryNav(c,DETAILS,"EDIT",r.disabilityId());}
 @Override @Transactional public DisabilityDeleteResponse delete(DisabilityRowRequest r){validateRow(r);String c=resolve(r.appOrCaseNum());int n=jdbc.update("DELETE FROM DC_DISABILITY WHERE APPLICATION_NO=? AND DISABILITY_ID=?",c,r.disabilityId());if(n==0)throw notFound(r.disabilityId());return new DisabilityDeleteResponse(c,r.disabilityId(),"DELETED");}
 @Override @Transactional(readOnly=true) public DisabilityDetailsInitializeResponse initializeDetails(DisabilityDetailsInitializeRequest r){String c=resolve(r==null?null:r.appOrCaseNum());ensureApplication(c);if(r.disabilityId()==null)return new DisabilityDetailsInitializeResponse(c,DETAILS,null,false);List<DisabilityDetails> rows=jdbc.query("SELECT d.*,p.FIRST_NAME,p.MIDDLE_NAME,p.LAST_NAME FROM DC_DISABILITY d JOIN DC_PERSON p ON p.PERSON_ID=d.PERSON_ID AND p.APPLICATION_NO=d.APPLICATION_NO WHERE d.APPLICATION_NO=? AND d.DISABILITY_ID=?",(s,n)->map(s),c,r.disabilityId());if(rows.isEmpty())throw notFound(r.disabilityId());return new DisabilityDetailsInitializeResponse(c,DETAILS,rows.get(0),true);}
 @Override @Transactional public DisabilityDetailsNavigationResponse detailsNext(DisabilityDetailsSaveRequest r){Saved s=save(r);return detailNav(s,"DC015");}
 @Override @Transactional public DisabilityDetailsNavigationResponse detailsPrevious(DisabilityDetailsSaveRequest r){Saved s=save(r);return detailNav(s,SUMMARY);}
 private Saved save(DisabilityDetailsSaveRequest r){if(r==null||r.disability()==null)throw bad("disability is required");String c=resolve(r.appOrCaseNum());ensureApplication(c);DisabilityDetails d=r.disability();validate(d);Person person=person(c,d.personId());LocalDate start=d.sameAsBirthDate()?person.dob():parseDate(d.disabilityStartDate());if(start==null)throw bad("disabilityStartDate is required");String joined=String.join(", ",normalizeTypes(d.disabilityTypes()));Long id=d.disabilityId();if(id==null)id=insert(c,d,start,joined);else update(c,id,d,start,joined);return new Saved(c,id);}
 private Long insert(String c,DisabilityDetails d,LocalDate start,String joined){KeyHolder k=new GeneratedKeyHolder();jdbc.update(con->{PreparedStatement p=con.prepareStatement("INSERT INTO DC_DISABILITY (APPLICATION_NO,PERSON_ID,DISABILITY_TYPES,OTHER_DISABILITY_DETAILS,PROOF_OF_DISABILITY,DISABILITY_START_DATE,SAME_AS_BIRTH_DATE) VALUES (?,?,?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS);bind(p,c,d,start,joined);return p;},k);if(k.getKey()==null)throw new IllegalStateException("DC_DISABILITY did not return a generated disabilityId");return k.getKey().longValue();}
 private void update(String c,Long id,DisabilityDetails d,LocalDate start,String joined){int n=jdbc.update("UPDATE DC_DISABILITY SET PERSON_ID=?,DISABILITY_TYPES=?,OTHER_DISABILITY_DETAILS=?,PROOF_OF_DISABILITY=?,DISABILITY_START_DATE=?,SAME_AS_BIRTH_DATE=? WHERE APPLICATION_NO=? AND DISABILITY_ID=?",d.personId(),joined,trim(d.otherDisabilityDetails()),d.proofOfDisability().trim(),java.sql.Date.valueOf(start),d.sameAsBirthDate(),c,id);if(n==0)throw notFound(id);}
 private void bind(PreparedStatement p,String c,DisabilityDetails d,LocalDate start,String joined)throws SQLException{p.setString(1,c);p.setLong(2,d.personId());p.setString(3,joined);p.setString(4,trim(d.otherDisabilityDetails()));p.setString(5,d.proofOfDisability().trim());p.setDate(6,java.sql.Date.valueOf(start));p.setBoolean(7,d.sameAsBirthDate());}
 private DisabilityDetails map(ResultSet s)throws SQLException{List<String> list=types(s.getString("DISABILITY_TYPES"));return new DisabilityDetails(s.getLong("DISABILITY_ID"),s.getLong("PERSON_ID"),name(s),list,String.join(", ",list),s.getString("OTHER_DISABILITY_DETAILS"),s.getString("PROOF_OF_DISABILITY"),s.getDate("DISABILITY_START_DATE").toLocalDate().toString(),s.getBoolean("SAME_AS_BIRTH_DATE"));}
 private void validate(DisabilityDetails d){if(d.personId()==null)throw bad("personId is required");if(normalizeTypes(d.disabilityTypes()).isEmpty())throw bad("at least one disability type is required");if(blank(d.proofOfDisability()))throw bad("proofOfDisability is required");if(normalizeTypes(d.disabilityTypes()).stream().anyMatch(x->x.equalsIgnoreCase("Other Disability"))&&blank(d.otherDisabilityDetails()))throw bad("otherDisabilityDetails is required for Other Disability");}
 private Person person(String c,Long id){List<Person> rows=jdbc.query("SELECT DATE_OF_BIRTH FROM DC_PERSON WHERE APPLICATION_NO=? AND PERSON_ID=?",(s,n)->new Person(s.getObject("DATE_OF_BIRTH",LocalDate.class)),c,id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Person record not found: "+id);return rows.get(0);}
 private List<String> normalizeTypes(List<String> values){if(values==null)return List.of();return values.stream().filter(v->v!=null&&!v.isBlank()).map(String::trim).distinct().toList();}private List<String> types(String value){return blank(value)?List.of():Arrays.stream(value.split(",")).map(String::trim).filter(v->!v.isEmpty()).toList();}
 private String name(ResultSet s)throws SQLException{return String.join(" ",java.util.stream.Stream.of(s.getString("FIRST_NAME"),s.getString("MIDDLE_NAME"),s.getString("LAST_NAME")).filter(v->v!=null&&!v.isBlank()).toList());}
 private String validateNav(DisabilitySummaryNavigationRequest r){String c=resolve(r==null?null:r.appOrCaseNum());ensureApplication(c);return c;}private void validateRow(DisabilityRowRequest r){if(r==null||r.disabilityId()==null)throw bad("disabilityId is required");}
 private void ensureApplication(String c){Integer n=jdbc.queryForObject("SELECT COUNT(*) FROM DC_APPLICATION WHERE APPLICATION_NO=?",Integer.class,c);if(n==null||n==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Data collection application not found: "+c);}private void ensureDisability(String c,Long id){Integer n=jdbc.queryForObject("SELECT COUNT(*) FROM DC_DISABILITY WHERE APPLICATION_NO=? AND DISABILITY_ID=?",Integer.class,c,id);if(n==null||n==0)throw notFound(id);}
 private String resolve(String v){String n=v==null?"":v.trim().toUpperCase(Locale.ROOT);if(!NUMBER.matcher(n).matches())throw bad("appOrCaseNum must match A or D followed by 7 digits");return n.startsWith("A")?"D"+n.substring(1):n;}private LocalDate parseDate(String v){if(blank(v))return null;try{return LocalDate.parse(v);}catch(DateTimeParseException e){throw bad("disabilityStartDate must use yyyy-MM-dd");}}
 private DisabilitySummaryNavigationResponse summaryNav(String c,String d,String m,Long id){return new DisabilitySummaryNavigationResponse(c,SUMMARY,d,m,id);}private DisabilityDetailsNavigationResponse detailNav(Saved s,String d){return new DisabilityDetailsNavigationResponse(s.caseNum(),s.id(),"SAVED",DETAILS,d);}private String trim(String v){return blank(v)?null:v.trim();}private boolean blank(String v){return v==null||v.isBlank();}private ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}private ResponseStatusException notFound(Long id){return new ResponseStatusException(HttpStatus.NOT_FOUND,"Disability record not found: "+id);}private record Person(LocalDate dob){}private record Saved(String caseNum,Long id){}
}
